(()=>{'use strict';
const A=window.ATLAS,G=window.GUIDES,$=s=>document.querySelector(s);
let lang;try{lang=localStorage.getItem('atlas-language')}catch{}lang=lang==='en'?'en':'zh';
const tr=(z,e)=>lang==='zh'?z:e, val=x=>typeof x==='object'&&x!==null?x[lang]??'':x??'';
const esc=x=>String(val(x)).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={home:['从这里开始','Start here'],map:['研究地图','Research map'],research:['论文与证据','Papers & evidence'],datasets:['数据与格式','Data & formats'],tools:['工具与 Agent','Tools & agents'],compute:['计算资源','Compute planning'],collections:['资源合集','Collections'],directions:['挑战与方向','Challenges & directions']};
const ev={association:['关联证据','Association'],prediction:['预测能力','Prediction'],experiment:['实验支持','Experimental support'],benchmark:['评测研究','Benchmark study'],workflow:['工具工作流','Tool workflow']};
const access={open:['公开访问','Open access'],controlled:['申请 / 受控','Controlled access'],mixed:['公开 + 受控','Mixed access']};
const kind={agent:['研究 Agent','Research agent'],registry:['工具注册表','Tool registry'],benchmark:['评测环境','Benchmark environment'],analysis:['分析工具','Analysis toolkit'],model:['领域模型','Domain model']};
let page='home',params=new URLSearchParams(),filters={q:'',domain:'',extra:''};
const label=(obj,k)=>tr(...obj[k]);
const external=(url,text,cls='source')=>`<a class="${cls}" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(text)} ↗</a>`;
const badge=(k)=>`<span class="pill ${k}">${esc(label(ev,k))}</span>`;
const heading=(eyebrow,title,desc)=>`<div class="page-head"><div class="eyebrow">${esc(eyebrow)}</div><h1>${esc(title)}</h1><p class="lead">${esc(desc)}</p></div>`;
const section=(title,sub='')=>`<div class="section-head"><h2>${esc(title)}</h2><span class="sub">${esc(sub)}</span></div>`;
const inline=ids=>`<div class="inline-resources">${ids.map(id=>{const r=A.research.find(x=>x.id===id);return r?`<a href="#research?id=${id}">${esc(r.name)}</a>`:''}).join('')}</div>`;
const detail=(title,content,cls='')=>`<div class="${cls}"><dt>${esc(title)}</dt><dd>${esc(content)}</dd></div>`;
const paper=r=>`<article class="card paper-card" id="resource-${r.id}"><div class="pills"><span class="pill">${r.year}</span>${badge(r.evidence)}<span class="pill">${esc(A.domains[r.domain])}</span></div><h3 class="paper-name">${esc(r.name)}</h3><div class="meta">${esc(r.venue)}</div><p class="resource-plain">${esc(r.plain)}</p><details ${params.get('id')===r.id?'open':''}><summary>${tr('数据、方法、结论与局限','Data, method, finding & limitation')}</summary><dl class="detail-list">${detail(tr('用什么数据','Data'),r.data)}${detail(tr('AI / 分析做什么','AI / analysis'),r.method)}${detail(tr('研究得到什么','Finding'),r.result)}${detail(tr('不要过度解读','Do not overinterpret'),r.limit,'caveat')}</dl></details><div class="link-row">${external(r.link,tr('论文原文','Primary paper'))}<a class="fine" href="#research?id=${r.id}" aria-label="${esc(tr('此条目链接','Permalink'))}"># ${r.id}</a></div></article>`;
const dataCard=d=>`<article class="card paper-card" id="resource-${d.id}"><div class="pills"><span class="pill">${esc(A.domains[d.domain])}</span><span class="pill ${d.access==='controlled'?'benchmark':'experiment'}">${esc(label(access,d.access))}</span></div><h3>${esc(d.name)}</h3><div class="meta">${esc(d.format)}</div><p class="resource-plain">${esc(d.plain)}</p><details ${params.get('id')===d.id?'open':''}><summary>${tr('结构、连接与注意事项','Structure, joins & cautions')}</summary><dl class="detail-list">${detail(tr('每条记录是什么','Unit of observation'),d.unit)}${detail(tr('用哪些字段连接','Join fields'),d.join)}${detail(tr('下载 / 使用之前','Before downloading or using'),d.pitfall,'caveat')}</dl></details>${external(d.link,tr('官方数据 / 访问说明','Official data / access instructions'))}</article>`;
const toolCard=t=>`<article class="card tool-card"><div class="pills"><span class="pill workflow">${esc(label(kind,t.kind))}</span></div><h3>${esc(t.name)}</h3><dl class="detail-list">${detail(tr('输入','Input'),t.input)}${detail(tr('产出','Output'),t.output)}</dl><details><summary>${tr('开放范围与使用边界','Availability & boundaries')}</summary><dl class="detail-list">${detail(tr('开放范围','Availability'),t.open)}${detail(tr('使用边界','Boundary'),t.limit,'caveat')}</dl></details>${external(t.link,tr('官方项目','Official project'))}</article>`;
function chrome(){
 document.documentElement.lang=lang==='zh'?'zh-CN':'en';$('#lang-toggle').textContent=lang==='zh'?'EN ↗':'中文 ↗';$('#glossary-toggle').textContent=tr('术语速查','Glossary');$('#nav-label').textContent=tr('研究导航','EXPLORE THE ATLAS');
 $('#nav').innerHTML=Object.keys(labels).map((key,i)=>`<a class="nav-item ${page===key?'active':''}" href="#${key}" ${page===key?'aria-current="page"':''}><span class="num">0${i+1}</span>${esc(label(labels,key))}</a>`).join('');
 $('#side-note').innerHTML=`<strong>${tr('证据优先 · 新手友好','Evidence first · Beginner friendly')}</strong>${tr('固定核查快照，不声称覆盖全部文献。','A verified snapshot, not a claim to cover all literature.')}<br>${tr('更新','Updated')} ${A.updated}<br><a href="#directions">${tr('范围与核查方法','Scope & curation method')} ↗</a>`;
 $('#footer').innerHTML=`<span>${tr('独立资源地图 · 生物医学研究用途 · 非医疗建议','Independent research atlas · Biomedical research · Not medical advice')}<br>${tr('来源为论文、官方数据文档及项目仓库；资源许可以原站为准。','Sources: papers, official data documentation and repositories. Original licenses apply.')}</span><span><a href="https://github.com/pILLOW-1/Awesome-AI-Health-Science/blob/main/CATALOG.md" target="_blank" rel="noopener noreferrer">${tr('完整文本目录','Full text catalog')} ↗</a> · <a href="https://github.com/pILLOW-1/Awesome-AI-Health-Science/issues" target="_blank" rel="noopener noreferrer">${tr('纠错 / 提交资源','Corrections / submissions')} ↗</a><br>Snapshot ${A.updated} · pILLOW-1</span>`;
 $('#glossary-title').textContent=tr('术语速查 · 不用先学一门生物学','Glossary · No biology degree required');
 $('#glossary-content').innerHTML=A.glossary.map(([en,zh,z,e])=>`<div class="glossary-row"><h3>${esc(lang==='zh'?zh:en)} <small>${esc(lang==='zh'?en:zh)}</small></h3><p>${esc(tr(z,e))}</p></div>`).join('');
}
function home(){const newest=[['2026.10.01','calibration26'],['2026.09.30','cytovi'],['2026.09.24','resolvi'],['2026.09.23','pascode'],['2026.09.16','paper2agent'],['2026.09.16','sciencebuddy']];return `<div class="hero"><div class="eyebrow">AI × BIOMEDICAL SCIENCE · AN EVIDENCE-FIRST ATLAS</div><h1>${tr('看懂 AI 如何研究疾病，<br>以及它还不能回答什么。','Understand how AI studies disease—<br>and what it cannot yet answer.')}</h1><p class="lead">${tr('从阿尔兹海默病到虚拟细胞，从数据文件到科研 Agent。把问题、数据、方法、证据和资源放在同一张地图里。','From Alzheimer’s disease to virtual cells; from data files to scientific agents. One map linking questions, data, methods, evidence and resources.')}</p><div class="buttons"><a class="button primary" href="#map">${tr('探索 8 条研究路线','Explore 8 research routes')} →</a><a class="button" href="#datasets">${tr('找到数据与格式','Find data & formats')} →</a></div></div><div class="stats">${[[A.research.length,tr('论文 / 研究','Studies')],[A.datasets.length,tr('数据资源','Datasets')],[A.tools.length,tr('工具 / Agent','Tools & agents')],[A.collections.length,tr('资源合集','Collections')]].map(([n,t])=>`<div class="stat"><strong>${n}</strong><span>${t}</span></div>`).join('')}</div><form id="home-search" class="search home-search" role="search"><input id="global-search" aria-label="${esc(tr('搜索全部资源','Search all resources'))}" placeholder="${esc(tr('搜索所有资源：AD、干预、H5AD、Agent… 按 Enter','Search all resources: AD, perturbation, H5AD, agents… Press Enter'))}"></form><div class="notice"><strong>${tr('先记住两件事：细胞 ≠ 患者，关联 ≠ 机制。','Remember: cells ≠ patients, and association ≠ mechanism.')}</strong> ${tr('数百万细胞可能只来自几十位供体；模型的高分不等于病因或疗效已被证明。','Millions of cells may come from only tens of donors; a high model score is not proof of causation or treatment benefit.')}</div>${section(tr('从你关心的问题开始','Start with your question'),tr('不需要先理解全部术语','No need to learn every term first'))}<div class="grid">${G.routes.slice(0,6).map((r,i)=>`<article class="card route-card"><span class="icon">${r.icon}</span><h3>${esc(r.title)}</h3><p>${esc(r.intro)}</p><a class="arrow-link" href="#map?id=${i}">${tr('问题 → 数据 → 挑战','Question → data → challenges')} →</a></article>`).join('')}</div>${section(tr('最近值得关注','Recent developments'),tr('发表 / 发布日期，不是网页抓取日期','Publication/release dates, not crawl dates'))}<div class="latest">${newest.map(([date,id])=>{const r=A.research.find(x=>x.id===id);return `<a href="#research?id=${id}"><time>${date}</time><strong>${esc(r.name)}</strong><span class="desc">${esc(r.plain)}</span><span>↗</span></a>`}).join('')}</div>${section(tr('证据怎样逐步变强？','How does evidence become stronger?'),tr('这不是每项研究必经的固定顺序','Not a fixed sequence for every study'))}<div class="evidence">${[[tr('观察关联','Association'),tr('哪些东西一起变化？','What changes together?'),tr('图谱、聚类和统计关联；可能有混杂。','Atlases, clusters and associations; confounding is possible.')],[tr('预测验证','Prediction'),tr('新数据上能预测吗？','Can it predict new data?'),tr('独立留出、合理基线和校准评测。','Independent holdouts, suitable baselines and calibrated metrics.')],[tr('干预支持','Intervention'),tr('改变它会造成结果吗？','Does changing it alter outcomes?'),tr('基因编辑、药理或功能实验；结论仍有语境。','Genetic, pharmacological or functional tests; still context-specific.')],[tr('患者获益','Patient benefit'),tr('对人是否有效且安全？','Is it effective and safe in people?'),tr('外部/前瞻研究与临床验证，不由前三项自动推出。','External/prospective studies and clinical validation; not implied by earlier levels.')]].map(([t,q,n],i)=>`<div class="card"><div class="step">0${i+1} / EVIDENCE</div><h3>${t}</h3><p>${q}<br>${n}</p></div>`).join('')}</div>${section(tr('给不同起点的阅读路线','Reading routes for different starting points'))}<div class="grid">${G.paths.map(p=>`<article class="card"><div class="reading-time">${esc(p.time)}</div><h3>${esc(p.title)}</h3><ol class="steps">${p.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol>${inline(p.ids)}</article>`).join('')}</div>${section(tr('容易误解的问题','Common misconceptions'))}${faq()}<div class="scope"><strong>${tr('覆盖范围','Scope')}</strong><span>${tr('重点是疾病机制、细胞/组织、干预、分子与科研代理；临床数据作连接场景。不覆盖整个 AI4Science 的物理、材料、天文文献。','Focus: disease mechanisms, cells/tissues, interventions, molecules and scientific agents, with clinical-data connections. Not an exhaustive map of physics, materials or astronomy.')}</span></div>`}
function faq(){return `<div class="faq">${[
 [tr('“虚拟细胞”是完整的人体细胞模拟吗？','Is a “virtual cell” a complete simulation of a human cell?'),tr('通常不是。很多模型预测的是表达、形态或某类条件下的响应，未覆盖全部代谢、空间、时间和分子过程。先问它预测什么读出、在哪些条件下验证。','Usually not. Many models predict expression, morphology or responses under specific conditions, not all metabolic, spatial, temporal and molecular processes. Ask what endpoint is predicted and under which validated conditions.')],
 [tr('为什么不能把细胞随机分成训练和测试？','Why not randomly split cells into training and test sets?'),tr('同一个供体、实验板或干预中的细胞可能共享很强的背景。随机拆开会把已知背景放进测试集，夸大新患者或新干预的能力。划分应匹配你的部署目标。','Cells from one donor, plate or intervention share background. Random splitting can put known context into the test set and exaggerate new-patient or new-intervention performance. Match the split to deployment.')],
 [tr('预测干预响应，就是发现因果机制吗？','Does predicting intervention responses reveal causal mechanisms?'),tr('不一定。干预数据提供更强的证据，但干预不完美、测量有限、细胞状态和培养环境会影响结果。预测正确也可能来自相关代理特征；机制需要明确假设与独立实验。','Not necessarily. Intervention data strengthen evidence, but imperfect interventions, limited measurements and experimental context affect results. Accurate predictions may use correlates; mechanisms require explicit assumptions and independent experiments.')],
 [tr('模型越大，结果就越好吗？','Are larger models always better?'),tr('不能这样判断。2025 年的扰动研究发现简单基线很强；2026 年的校准研究又说明指标本身会改变判断。需要在同一任务、数据与划分下比较，而不是按参数量选择。','No. A 2025 perturbation study found strong simple baselines; 2026 calibration research showed metric choice changes conclusions. Compare models on identical tasks, data and splits, rather than choosing by parameter count.')],
 [tr('Agent 和领域模型有什么区别？','What is the difference between an agent and a domain model?'),tr('领域模型预测序列、结构或细胞响应；Agent 规划工作、调用工具和解释结果。Agent 可以使用这些模型，但“流程跑通”与“科学结论正确”是两种验证。','Domain models predict sequence, structure or cell responses. Agents plan work, call tools and interpret results. Agents may use those models, but successful execution and scientific correctness are separate checks.')],
 [tr('公开下载意味着可以任意使用吗？','Does public access mean unrestricted use?'),tr('不是。代码、权重、输出、数据和外部 API 可能有不同许可；有些限制商业用途，有些需要数据申请或禁止外传。数据访问规则以官方当前文档为准。','No. Code, weights, outputs, data and external APIs can have different licenses, commercial restrictions or access requirements. Follow current official policies, including limits on external transfer.')]
].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div>`}
function map(){return heading('QUESTIONS → DATA → EVIDENCE',tr('八条研究路线，一张问题地图','Eight routes, one question map'),tr('这里回答“研究什么、数据是什么、难在哪里、下一步怎么做”。未来方向是编辑综合，不是原论文保证。','What is studied, what data are used, what is difficult, and what comes next. Future directions are editorial synthesis, not paper guarantees.'))+G.routes.map((r,i)=>`<article class="card route-detail" id="route-${i}"><div class="eyebrow">ROUTE ${r.icon}</div><h2>${esc(r.title)}</h2><p class="intro">${esc(r.intro)}</p><div class="four">${[[tr('研究问题','Research question'),r.question],[tr('需要的数据','Data needed'),r.data],[tr('当前挑战','Current challenge'),r.challenge],[tr('值得探索的方向','Promising direction'),r.next]].map(([h,p])=>`<div><h4>${h}</h4><p>${esc(p)}</p></div>`).join('')}</div>${inline(r.ids)}</article>`).join('')}
function toolbar(type){let options=type==='tools'?Object.keys(kind).map(k=>`<option value="${k}">${esc(label(kind,k))}</option>`):Object.keys(A.domains).filter(k=>(type==='research'?A.research:A.datasets).some(x=>x.domain===k)).map(k=>`<option value="${k}">${esc(A.domains[k])}</option>`);let extras=type==='research'?Object.keys(ev).map(k=>`<option value="${k}">${esc(label(ev,k))}</option>`):type==='datasets'?Object.keys(access).map(k=>`<option value="${k}">${esc(label(access,k))}</option>`):[];return `<div class="toolbar" role="search"><div class="search"><input id="search" value="${esc(filters.q)}" aria-label="${esc(tr('关键词搜索','Keyword search'))}" placeholder="${esc(tr('搜索名称、疾病、方法、格式…','Search names, diseases, methods, formats…'))}"></div><select id="domain" aria-label="${esc(tr('方向 / 类型筛选','Domain / type filter'))}"><option value="">${tr('全部方向 / 类型','All domains / types')}</option>${options.join('')}</select>${extras.length?`<select id="extra" aria-label="${esc(tr('证据 / 权限筛选','Evidence / access filter'))}"><option value="">${tr('全部证据 / 权限','All evidence / access')}</option>${extras.join('')}</select>`:''}<button id="reset" class="quiet">${tr('重置','Reset')}</button></div><div class="result-line"><span id="result-count" aria-live="polite"></span><button id="expand" class="quiet">${tr('展开细节','Expand details')}</button></div><div class="grid" id="results"></div>`}
function library(type){const text={research:['PAPERS & EVIDENCE',tr('论文要读结论，也要读边界','Read findings—and their boundaries'),tr('经典方法与截至 2026 年 10 月的前沿工作。标签描述研究提供哪种证据，不是期刊或模型排名。部分条目以实验或数据为主，并不使用 AI。','Classic methods and frontier work through October 2026. Tags describe evidence, not journal or model rankings. Some experimental/data studies do not themselves use AI.')],datasets:['DATASETS & SCHEMAS',tr('数据先看结构，再看规模','Understand structure before scale'),tr('每个资源说明记录单位、文件格式、连接键和使用陷阱。这里只提供公开说明与访问链接，不镜像患者数据。','Each resource explains observation units, formats, joins and pitfalls. Public descriptions/access routes only; no patient-data mirrors.')],tools:['TOOLS, MODELS & AGENTS',tr('选工具，先看它实际做什么','Choose tools by what they actually do'),tr('区分研究代理、领域模型、工具库与评测环境。公开代码不代表完整产品开放，也不代表数据、权重可无限制使用。','Distinguish agents, domain models, toolkits and evaluation environments. Public code does not imply full-product availability or unrestricted data/weights.')]};let out=heading(...text[type]);if(type==='datasets')out+=`<div class="notice warm"><strong>${tr('下载前先检查授权。','Check permissions before downloading.')}</strong> ${tr('尤其是 AMP-AD / ROSMAP、ADNI 和 MIMIC。受控数据的衍生文件、嵌入与模型输出也可能受协议约束；不要直接发给外部 LLM。','Especially AMP-AD/ROSMAP, ADNI and MIMIC. Derivatives, embeddings and model outputs may remain restricted; do not send them directly to external LLMs.')}</div>`;if(type==='research')out+=`<div class="legend">${tr('证据标签：','Evidence tags:')} ${Object.keys(ev).map(badge).join('')}</div>`;out+=toolbar(type);if(type==='datasets')out+=section(tr('文件格式，一眼看懂','File formats at a glance'),tr('结构示意，不是实际患者数据','Illustrative schemas, not patient records'))+`<div class="grid">${G.formats.map(f=>`<article class="card"><h3>${esc(f.name)}</h3><p>${esc(f.meaning)}</p><pre class="code">${esc(f.example)}</pre><div class="format-check">${esc(f.check)}</div>${external(f.url,tr('官方格式说明','Official format documentation'))}</article>`).join('')}</div>`;return out}
function results(){const pool=page==='research'?A.research:page==='datasets'?A.datasets:A.tools;let list=pool.filter(x=>(!filters.domain||(page==='tools'?x.kind:x.domain)===filters.domain)&&(!filters.extra||(page==='research'?x.evidence:x.access)===filters.extra)&&JSON.stringify(x).toLocaleLowerCase().includes(filters.q.toLocaleLowerCase().trim()));if(page==='research')list=list.slice().sort((a,b)=>b.year-a.year);let focus=params.get('id');if(focus)list.sort((a,b)=>Number(b.id===focus)-Number(a.id===focus));$('#result-count').textContent=tr(`显示 ${list.length} / ${pool.length} 个条目`,`Showing ${list.length} / ${pool.length} entries`);$('#results').innerHTML=list.length?list.map(page==='research'?paper:page==='datasets'?dataCard:toolCard).join(''):`<div class="empty">${tr('没有匹配结果。试试英文缩写，或重置筛选。','No matches. Try an acronym or reset the filters.')}</div>`;const target=focus&&document.getElementById('resource-'+focus);if(target)target.style.borderColor='#8b83d8'}
function compute(){return heading('HARDWARE · MEMORY · REALISTIC STARTING POINTS',tr('算力预算，不要只看 GPU','Compute planning is more than GPUs'),tr('把官方测试配置与规划估算严格分开。估算用于选起步路线，不是最低规格、费用报价或性能承诺；先用小样本实际测峰值。','Official configurations and planning estimates are separate. Estimates guide starting routes—not minimums, price quotes or performance promises. Pilot peak usage first.'))+`<div class="notice green"><strong>${tr('最低门槛：公开小样本 + CPU + 简单基线。','Lowest-friction start: a small public sample, CPU and simple baselines.')}</strong> ${tr('API Agent 可不需要本地 GPU；原始测序、数据库搜索、影像读取和湿实验预算应另外计算。','API agents may need no local GPU; raw sequencing, database search, image I/O and wet-lab costs are separate.')}</div><div class="table-wrap"><table><thead><tr>${[tr('任务','Task'),tr('性质','Status'),'GPU / VRAM','RAM',tr('存储','Storage'),tr('使用条件与来源','Conditions & source')].map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${G.compute.map(r=>`<tr><td><strong>${esc(r.task)}</strong></td><td><span class="pill ${r.mode==='reported'?'experiment':'benchmark'}">${r.mode==='reported'?tr('官方报告','Official report'):tr('规划估算','Planning estimate')}</span></td><td>${esc(r.gpu)}</td><td>${r.ram}</td><td>${r.disk}</td><td>${esc(r.note)}<br>${external(r.url,tr('依据 / 文档','Basis / docs'))}</td></tr>`).join('')}</tbody></table></div>${section(tr('一个容易踩的坑：把稀疏矩阵变成密集矩阵','A common trap: turning sparse matrices dense'))}<div class="card calc"><div><h3>${tr('密集表达矩阵内存计算','Dense expression-matrix memory')}</h3><p>${tr('float32：细胞数 × 基因数 × 4 字节。只算一份矩阵，不含副本、元数据、梯度或模型。','float32: cells × genes × 4 bytes. One matrix only; excludes copies, metadata, gradients and models.')}</p><div class="calc-inputs"><label>${tr('细胞数','Cells')}<input id="cells" type="number" min="1" max="1000000000" value="1000000"></label><label>${tr('基因数','Genes')}<input id="genes" type="number" min="1" max="1000000" value="20000"></label></div></div><div class="calc-output"><strong id="memory"></strong><p id="memory-note"></p></div></div>${section(tr('权重大小 ≠ 运行显存','Weight size ≠ runtime memory'))}<div class="grid"><article class="card"><h3>${tr('先算权重，再留运行空间','Count weights, then allow runtime space')}</h3><p>${tr('BF16 / FP16 每参数约 2 字节。7B 权重约 14 GB，40B 约 80 GB，仅为权重理论大小；还需激活、缓存、上下文和框架开销。训练另有梯度与优化器状态。','BF16/FP16 uses about two bytes per parameter. 7B ≈14 GB and 40B ≈80 GB for weights alone; activations, caches, context and framework overhead are additional. Training adds gradients and optimizer states.')}</p></article><article class="card"><h3>${tr('先做小样本压力测试','Pilot a representative workload')}</h3><p>${tr('记录输入大小、精度、batch、峰值显存/RAM、运行时间和 I/O。公开 A100/H100 时间不是你的整条流程时间。全量预训练和小规模微调不能用同一预算。','Record input size, precision, batch, peak VRAM/RAM, runtime and I/O. Published A100/H100 timings are not your full-pipeline timings. Full pretraining and small fine-tuning require different budgets.')}</p></article></div>`}
function collections(){return heading('CURATED COLLECTIONS',tr('哪些仓库能串起论文、数据与工具？','Which collections connect papers, data and tools?'),tr('没有一个仓库完整覆盖疾病机制 + 全部数据格式 + Agent + 算力。下面这些入口互补，本地图负责把它们按问题串起来；不以星数判断可靠性。','No single repository completely covers disease mechanisms, all schemas, agents and compute. These collections complement one another; this atlas connects them by question. Stars are not evidence of reliability.'))+`<div class="grid">${A.collections.map(c=>`<article class="card"><span class="pill">${esc(c.coverage)}</span><h3 style="margin-top:13px">${esc(c.name)}</h3><p>${esc(c.desc)}</p>${external(c.url,tr('打开合集','Open collection'))}</article>`).join('')}</div><div class="notice quickstart"><strong>${tr('最接近你的 1 + 2 + 3：','Closest to your papers + data + tools request:')}</strong> OmicsML + Awesome Virtual Cell + Awesome AI for Science. ${tr('再用 Science Agents 补代理，用官方数据字典补格式与权限。','Add Science Agents for agents and official dictionaries for schemas/permissions.')}</div>`}
function directions(){return heading('GAPS → TESTABLE RESEARCH',tr('把挑战变成可检验的研究方向','Turn challenges into testable research'),tr('以下是对多项工作的综合判断，不是已有方法的性能保证。每条方向都给出数据链和验证目标，避免只有“未来很有潜力”。','Editorial synthesis across studies, not performance guarantees. Each direction includes a data chain and validation target rather than only claims of potential.'))+`<div class="grid">${G.opportunities.map(o=>`<article class="card"><h3>${esc(o.title)}</h3><dl class="detail-list">${detail(tr('缺口是什么','Gap'),o.why)}${detail(tr('可做的设计','Possible design'),o.design)}${detail(tr('怎样证明有用','Validation target'),o.test,'caveat')}</dl></article>`).join('')}</div>${section(tr('开始实验前的检查单','Before starting an experiment'))}<div class="checklist">${G.checklist.map(t=>`<div class="check-item"><span>✓</span>${esc(t)}</div>`).join('')}</div>${section(tr('范围、日期与核查方法','Scope, dates and curation method'))}<div class="card"><dl class="detail-list">${detail(tr('定位','Purpose'),tr('面向非领域读者的生物医学研究导航，连接疾病机制、细胞病理、因果、数据、工具与资源。不是系统综述、临床指南或穷尽清单。','Biomedical research navigation for non-specialists, linking mechanisms, cell pathology, causality, data, tools and resources. Not a systematic review, clinical guideline or exhaustive list.'))}${detail(tr('选源','Sources'),tr('优先论文原文、作者项目、官方数据/格式文档。附件 PDF 作为线索，不直接复用未核实论断；没有公开原始附件。','Prefer primary papers, author projects and official data/schema documentation. Supplied PDFs were leads, not authority for unverified claims; original attachments are not published.'))}${detail(tr('年份与数量','Dates & counts'),tr('区分预印本与正式发表，部分模型早期版本先于本条列出的期刊年份。细胞数、供体数、全语料与过滤分析子集分开。资源计数是本目录条目数，不是领域总数。','Distinguish preprints and journal publication; earlier model versions may precede the listed journal year. Separate cells, donors, full corpora and filtered analyses. Counts describe catalog entries, not the whole field.'))}${detail(tr('核查快照','Snapshot'),tr('核查截至 2026-10-08。资源、许可和政策会变化；核查入口链接不等于下载或成功复现全部模型。本地聚合检索脚本失败后采用逐项原始来源核查。','Checked through 2026-10-08. Resources, licenses and policies change; checking source links is not downloading or reproducing every model. Primary-source review substituted for a failed local aggregation script.'))}${detail(tr('维护与纠错','Maintenance'),tr('GitHub 中维护可读目录、结构化内容、更新日志和核查规则。本版本是固定快照，不会在未配置更新任务时自动追踪新论文。通过 Issues 提交论文、官方链接、改动理由与证据。','GitHub maintains a readable catalog, structured content, changelog and curation rules. This is a fixed snapshot, not an automatic literature monitor. Submit papers, official links, rationale and evidence through Issues.'))}</dl>${external('https://github.com/pILLOW-1/Awesome-AI-Health-Science',tr('查看源码与维护规则','View source & maintenance rules'))}</div>`}
function searchAll(){const q=(params.get('q')||'').trim(),needle=q.toLocaleLowerCase();const rp=A.research.filter(x=>JSON.stringify(x).toLocaleLowerCase().includes(needle)),ds=A.datasets.filter(x=>JSON.stringify(x).toLocaleLowerCase().includes(needle)),ts=A.tools.filter(x=>JSON.stringify(x).toLocaleLowerCase().includes(needle));return heading('SEARCH THE ATLAS',tr(`搜索：${q}`,`Search: ${q}`),tr(`${rp.length+ds.length+ts.length} 个匹配条目。跨论文、数据与工具搜索。`,`${rp.length+ds.length+ts.length} matching entries across papers, data and tools.`))+`<a class="button" href="#home">← ${tr('返回首页','Back to start')}</a>`+(rp.length?section(tr('论文','Papers'))+`<div class="grid">${rp.map(paper).join('')}</div>`:'')+(ds.length?section(tr('数据','Datasets'))+`<div class="grid">${ds.map(dataCard).join('')}</div>`:'')+(ts.length?section(tr('工具','Tools'))+`<div class="grid">${ts.map(toolCard).join('')}</div>`:'')+(!rp.length&&!ds.length&&!ts.length?`<p class="empty">${tr('没有找到，试试英文缩写或更短的关键词。','No matches; try an acronym or shorter keyword.')}</p>`:'')}
function render(keepScroll=false){const raw=(location.hash||'#home').slice(1).split('?');page=raw[0];params=new URLSearchParams(raw[1]||'');if(!labels[page]&&page!=='search')page='home';chrome();$('#main').innerHTML=page==='home'?home():page==='map'?map():['research','datasets','tools'].includes(page)?library(page):page==='compute'?compute():page==='collections'?collections():page==='search'?searchAll():directions();document.title=page==='search'?'Search · AI Health & Science Atlas':label(labels,page)+' · AI Health & Science Atlas';if(['research','datasets','tools'].includes(page)){ $('#domain').value=filters.domain;if($('#extra'))$('#extra').value=filters.extra;results();$('#search').addEventListener('input',e=>{filters.q=e.target.value;results()});$('#domain').addEventListener('change',e=>{filters.domain=e.target.value;results()});$('#extra')?.addEventListener('change',e=>{filters.extra=e.target.value;results()});$('#reset').addEventListener('click',()=>{filters={q:'',domain:'',extra:''};params.delete('id');$('#search').value='';$('#domain').value='';if($('#extra'))$('#extra').value='';results()});$('#expand').addEventListener('click',e=>{const nodes=[...$('#results').querySelectorAll('details')],open=nodes.some(d=>!d.open);nodes.forEach(d=>d.open=open);e.target.textContent=open?tr('收起细节','Collapse details'):tr('展开细节','Expand details')})}if($('#home-search'))$('#home-search').insertAdjacentHTML('beforeend',`<button class="button primary" type="submit">${tr('搜索','Search')} →</button>`);$('#home-search')?.addEventListener('submit',e=>{e.preventDefault();const q=$('#global-search').value.trim();if(q)location.hash='search?q='+encodeURIComponent(q)});if(page==='compute'){const calc=()=>{let cells=Number($('#cells').value),genes=Number($('#genes').value);const gb=cells*genes*4/1e9;$('#memory').textContent=cells>0&&genes>0&&Number.isFinite(gb)?`${gb.toLocaleString(lang,{maximumFractionDigits:2})} GB`:'—';$('#memory-note').textContent=tr('默认示例：一份 100 万 × 2 万的 float32 矩阵约 80 GB。稀疏存储按非零元素数量计算，可大幅降低。','Default: one 1M × 20k float32 matrix is about 80 GB. Sparse storage scales with nonzero entries and can be much smaller.')};$('#cells').addEventListener('input',calc);$('#genes').addEventListener('input',calc);calc()}if(!keepScroll){window.scrollTo(0,0);if(page==='map'&&params.has('id'))setTimeout(()=>document.getElementById('route-'+params.get('id'))?.scrollIntoView({block:'center'}),0)}}
$('#lang-toggle').addEventListener('click',()=>{lang=lang==='zh'?'en':'zh';try{localStorage.setItem('atlas-language',lang)}catch{}render(true)});$('#glossary-toggle').addEventListener('click',()=>$('#glossary').showModal());$('#glossary-close').addEventListener('click',()=>$('#glossary').close());$('#glossary').addEventListener('click',e=>{if(e.target===$('#glossary')){const r=$('#glossary').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#glossary').close()}});window.addEventListener('hashchange',()=>{filters={q:'',domain:'',extra:''};render()});render();
})();
